const cleanBlock = (a) => {
  a.innerHTML = ''
}
export const renderTemplate = (parsedHTML, a, updateState, variableChange, tag, tagIndex, contentType) => {
  cleanBlock(a)
  const listData = parsedHTML.querySelectorAll('.template-content-change .template-content-list')
  const normalData = parsedHTML.querySelectorAll('.template-content-change .template-content')
  const tableKey = parsedHTML.querySelectorAll('.template-content-change-table .template-content-key')
  const tableValue = parsedHTML.querySelectorAll('.template-content-change-table .template-content-value')
  if (listData.length>0) {
    renderListTemplate(parsedHTML, a, updateState, variableChange, tag, tagIndex, contentType)
  }
  if (normalData.length>0) {
    renderNormalTemplate(parsedHTML, a, updateState, variableChange, tag, tagIndex, contentType)
  }
  if (tableKey.length>0 && tableValue.length>0) {
    renderTableTemplate(parsedHTML, a, updateState, variableChange, tag, tagIndex, contentType)
  }
}
const renderListTemplate = (parsedHTML, a, updateState, variableChange, tag, tagIndex, contentType) => {
  const data = parsedHTML.querySelectorAll('.template-content-change .template-content-list')
  if (contentType === 'list') {
    if (!!variableChange && !!tag) {
      const array = tag.innerHTML
      tag.innerHTML = array.replace(/{{}}/g, `{{${variableChange}}}`)
      data[tagIndex].innerHTML = tag.innerHTML
      updateState(parsedHTML, '', '', '')
    }
  }
  for (let i = 0; i < data.length; i++) {
    const b = document.createElement('input')
    const buttonDelete = document.createElement('INPUT')
    const outerDiv = document.createElement('DIV')
    const lineBreakTag = document.createElement('br')
    const labelTag = document.createElement('label')
    outerDiv.setAttribute('class', 'key-field')
    b.setAttribute('class', 'key-field')
    b.setAttribute('type', 'text')
    buttonDelete.setAttribute('type', 'button')
    buttonDelete.setAttribute('class', 'delete-button')
    labelTag.innerText = `${i + 1}`
    outerDiv.appendChild(labelTag)
    outerDiv.appendChild(lineBreakTag)
    b.value = data[i].innerText
    b.innerHTML = data[i].innerText
    outerDiv.appendChild(b)
    outerDiv.appendChild(buttonDelete)
    outerDiv.appendChild(lineBreakTag)

    b.addEventListener('input', function (e) {
      data[i].innerText = e.target.value
      updateState(parsedHTML, data[i], i, 'list')
    })
    buttonDelete.addEventListener('click', function (e) {
      data[i].remove()
      outerDiv.remove()
      updateState(parsedHTML)
    }, { capture: true })
    a.appendChild(outerDiv)
  }
}

const renderTableTemplate = (parsedHTML, a, updateState, variableChange, tag, tagIndex, contentType) => {
  const dataKeys = parsedHTML.querySelectorAll('.template-content-change-table .template-content-key')
  const dataValues = parsedHTML.querySelectorAll('.template-content-change-table .template-content-value')

  if (contentType === 'tableKey') {
    if (!!variableChange && !!tag) {
      const array = tag.innerHTML
      tag.innerHTML = array.replace(/{{}}/g, `{{${variableChange}}}`)
      dataKeys[tagIndex].innerHTML = tag.innerHTML
      updateState(parsedHTML, '', '', '')
    }
  }
  if (contentType === 'tableValue') {
    if (!!variableChange && !!tag) {
      const array = tag.innerHTML
      tag.innerHTML = array.replace(/{{}}/g, `{{${variableChange}}}`)
      dataValues[tagIndex].innerHTML = tag.innerHTML
      updateState(parsedHTML, '', '', '')
    }
  }
  for (let i = 0, j = 0; (i < dataKeys.length && j < dataValues.length); i++, j++) {
    const deletTag = document.createElement('input')
    const inputTagKey = document.createElement('input')
    const inputTagValue = document.createElement('input')
    const labelTag = document.createElement('label')
    const outerDiv = document.createElement('DIV')
    const lineBreakTag = document.createElement('br')

    outerDiv.setAttribute('class', 'key-field')
    inputTagKey.setAttribute('class', 'input-filed')
    inputTagValue.setAttribute('class', 'input-filed')
    inputTagKey.setAttribute('type', 'text')
    inputTagValue.setAttribute('type', 'text')
    inputTagKey.setAttribute('name', i)
    inputTagValue.setAttribute('name', j)
    deletTag.setAttribute('type', 'button')
    deletTag.setAttribute('class', 'delete-button')
    deletTag.setAttribute('name', i)
    outerDiv.appendChild(labelTag)
    outerDiv.appendChild(lineBreakTag)
    inputTagKey.value = dataKeys[i].innerText
    inputTagKey.innerHTML = dataKeys[i].innerText
    inputTagValue.value = dataValues[i].innerText
    inputTagValue.innerHTML = dataValues[i].innerText
    outerDiv.appendChild(inputTagKey)
    outerDiv.appendChild(inputTagValue)
    outerDiv.appendChild(deletTag)

    inputTagKey.addEventListener('input', function (e) {
      dataKeys[e.target.name].innerText = e.target.value
      updateState(parsedHTML, dataKeys[e.target.name], i, 'tableKey')
    })

    inputTagValue.addEventListener('input', function (e) {
      dataValues[e.target.name].innerText = e.target.value
      updateState(parsedHTML, dataValues[e.target.name], j, 'tableValue')
    })
    deletTag.addEventListener('click', function (e) {
      dataKeys[i].parentNode.remove()
      outerDiv.remove()
      updateState(parsedHTML)
    }, { capture: true })
    a.appendChild(outerDiv)
  }
}
export const hrefChange = (data) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g
  return data.replace(urlRegex, function (url) {
    return '<a href="' + url + '">' + url + '</a>'
  })
}
const renderNormalTemplate = (parsedHTML, a, updateState, variableChange, tag, tagIndex, contentType) => {
  const data = parsedHTML.querySelectorAll('.template-content-change .template-content')
  if (contentType === 'normal') {
    if (variableChange && tag) {
      // The constructor function is particularly useful when you want to dynamically generate the pattern,
      // because it takes string arguments.
      const array = tag.innerHTML
      tag.innerHTML = array.replace(/{{}}/g, `{{${variableChange}}}`)
      data[tagIndex].innerHTML = tag.innerHTML
      updateState(parsedHTML, '', '', '')
    }
  }
}
