
import { Button, Upload } from 'antd'
import { useEffect, useState } from 'react'
import ModalDiv from './index.style'
export const HeaderImage = ({tagSelected, html, dummyRequest, onChange, onClick }) => {
    const [viewType, setViewType] = useState(null)
    const [children, setChildren] = useState([])
    useEffect(() => {
        const logoContainer = html.querySelector('.template-logo');
        if (logoContainer.children.length > 0) {
            setViewType("multiple")
            // setChildren(logoContainer.children)
        }
        else {
            setViewType("single")
        }
    },[])
    useEffect(()=>{
        const logoContainer = html.querySelector('.template-logo');
        const htmlchildren = logoContainer.children;
        if(htmlchildren.length > 0 && viewType==="single"){
            const filledArray = Array(htmlchildren.length).fill(0);
            setViewType("multiple");
            setChildren(filledArray)
        }
        else if(htmlchildren.length>children.length){
            const filledArray = Array(htmlchildren.length).fill(0);
            setChildren(filledArray)
        }
    })
    if (!viewType) {
        return (
            <div>Loading..</div>
        )
    }
    return (
        <ModalDiv>
            {
                viewType === "single" ?
                    <Upload
                        name='file'
                        showUploadList={false}
                        multiple={false}
                        customRequest={dummyRequest}
                        onChange={file => onChange(file)}
                    >
                        <Button
                            className='ant-btn-radius'
                            onClick={() => onClick('logo', 0)}
                        >
                            Add Header Image
                        </Button>
                    </Upload>
                    :
                    <>
                        {
                            children.map((ele, idx) => (
                                <Upload
                                    name='file'
                                    showUploadList={false}
                                    multiple={false}
                                    customRequest={dummyRequest}
                                    onChange={file => onChange(file)}
                                    key={idx}
                                >
                                    <Button
                                        className='ant-btn-radius'
                                        onClick={() => onClick('logo', idx)}
                                    >
                                        Change Header Image
                                    </Button>
                                </Upload>
                            ))
                        }
                        <Upload
                            name='file'
                            showUploadList={false}
                            multiple={false}
                            customRequest={dummyRequest}
                            onChange={file => onChange(file)}
                        >
                            <Button
                                className='ant-btn-radius'
                                onClick={() => onClick('logo', children.length)}
                            >
                                Add Header Image
                            </Button>
                        </Upload>
                    </>

            }

        </ModalDiv>
    )
}