import React, { useState, useEffect, useRef, useMemo } from 'react'
import { Spin, Modal, Input, Form, message } from 'antd'

import { connect } from 'react-redux'
import ReactQuill from 'react-quill'
import TextEditorV2Div from './index.style'
import notificationActions from '../../PasarApp/redux/notifications/actions'
import axios from 'axios'
import exportObj from '../../config/urls'
import { getHeaderUploadFile } from '../../helpers/utility'
import { BASE_IMG_URL_S3 } from '../../helpers/constant'
import { TEXT_EDITOR_FORMATS, getTextEditorModules } from './quill'

const { startUploadTemplate, resetNotificationsRedux, resetNotificationCore } =
  notificationActions

const FormItem = Form.Item

function TextEditor (props) {
  const { previousContent, updateContent, form } = props
  const quillRef = useRef()
  const [value, setValue] = useState('')
  const [imageUpload, setImageUpload] = useState(false)
  const [isModalVisible, setIsModalVisible] = useState(false)
  const [pendingImageFile, setPendingImageFile] = useState(null)

  const setValue1 = (newValue) => {
    setValue(newValue)
  }

  const handleImageUpload = async (uploadHeight, uploadWidth) => {
    if (!pendingImageFile) return

    const editor = quillRef.current.getEditor()
    const formData = new FormData()
    formData.append('file', pendingImageFile)

    setImageUpload(true)
    try {
      const res = await axios.post(
        exportObj.url.templateNotificationUpload,
        formData,
        { headers: getHeaderUploadFile() }
      )

      const url =
        res?.data?.url ||
        `${BASE_IMG_URL_S3}/templates/service_center/pending_device_recevied_by_customer.png`
      const index = editor.getSelection()?.index || 0
      editor.insertEmbed(index, 'image', {
        url,
        width: uploadWidth,
        height: uploadHeight
      })
      editor.setSelection(index + 1, 0)

      setValue(editor.root.innerHTML)
    } catch (error) {
      message.error('Failed to upload image')
    } finally {
      setImageUpload(false)
      setPendingImageFile(null)
    }
  }

  const handleModalOk = () => {
    form.validateFields((err, values) => {
      if (!err) {
        handleImageUpload(values.height, values.width)
        setIsModalVisible(false)
        form.resetFields()
      }
    })
  }

  const handleModalCancel = () => {
    setIsModalVisible(false)
    setPendingImageFile(null)
    form.resetFields()
  }

  const modulesQuill = useMemo(
    () =>
      getTextEditorModules({
        setPendingImageFile,
        setIsModalVisible,
        message
      }),
    [setPendingImageFile, setIsModalVisible]
  )

  const formatsQuill = TEXT_EDITOR_FORMATS

  useEffect(() => {
    if (previousContent) {
      const parser = new DOMParser()
      const parsedHTML = parser.parseFromString(previousContent, 'text/html')
      const templateContentChange = parsedHTML.querySelector('.template-content')

      if (!templateContentChange) return

      const tempHtml = templateContentChange.innerHTML
      if (tempHtml.trim().length !== 0) {
        const trimmed = tempHtml.trim()
        setValue(trimmed)

        if (quillRef.current) {
          const editor = quillRef.current.getEditor()
          editor.clipboard.dangerouslyPasteHTML(trimmed)
          editor.setSelection(editor.getLength(), 0)
        }
      }
    }
  }, [])

  useEffect(() => {
    if (value.length !== 0) {
      updateContent(value, 'content')
    }
  }, [updateContent, value])

  return (
    <Spin spinning={imageUpload} tip='Updating Your Image'>
      <TextEditorV2Div>
        <ReactQuill
          theme='snow'
          value={value}
          onChange={setValue1}
          modules={modulesQuill}
          formats={formatsQuill}
          ref={quillRef}
        />
      </TextEditorV2Div>

      <Modal
        title='Set Image Dimensions'
        visible={isModalVisible}
        onOk={handleModalOk}
        onCancel={handleModalCancel}
        okText='Upload'
        cancelText='Cancel'
      >
        <Form layout='vertical'>
          <FormItem label='Height (px)'>
            {form.getFieldDecorator('height', {
              initialValue: '200',
              rules: [
                { required: true, message: 'Please enter height' },
                { pattern: /^\d+$/, message: 'Please enter a valid number' }
              ]
            })(<Input type='number' placeholder='Enter height' />)}
          </FormItem>
          <FormItem label='Width (px)'>
            {form.getFieldDecorator('width', {
              initialValue: '200',
              rules: [
                { required: true, message: 'Please enter width' },
                { pattern: /^\d+$/, message: 'Please enter a valid number' }
              ]
            })(<Input type='number' placeholder='Enter width' />)}
          </FormItem>
        </Form>
      </Modal>
    </Spin>
  )
}

export default Form.create()(
  connect(
    (state) => ({
      UploadDataUrl: state.Notifications.templateUploadURl,
      uploadingImageLoading:
        state.Loading.UPLOAD_NOTIFICATIONS_TEMPLATE_ATTRIBUTE,
      UploadDataUrlMessage: state.Notifications.templateUploadURlMessage
    }),
    {
      startUploadTemplate,
      resetNotificationsRedux,
      resetNotificationCore
    }
  )(TextEditor)
)
