import { useState } from "react";
import ColorPickerDiv1 from "./index.style";
import { RIGHT_ARROW } from "../../PasarApp/containers/Agent/constants";

const colors = [
  "#FAF000",
  "#FA8200",
  "#FA3C46",
  "#FA64C8",
  "#B43CFA",
  "#00B4FA",
  "#00D278",
  "#FAFA96",
  "#FADCBE",
  "#FAD2D2"
]

function ColorPicker({updateBgColor}) {
  const [sketchPickerColor, setSketchPickerColor] = useState("#FFFFFF");
  const handleChange = (e)=>{
    setSketchPickerColor(e.target.value)
  }
  return (
    <ColorPickerDiv1>
      <div className="first-row">
        <p className="text">Color</p>
        <div className="input-box-container">
          <input onChange={handleChange} value={sketchPickerColor} className="color-input"/>
          <div  onClick={()=>updateBgColor(sketchPickerColor)} className="blue-box">
            <img src={RIGHT_ARROW} alt="RIGHT_ARROW"/>
          </div>
        </div>
       

      </div>
      <div className="second-row">
          <div onClick={()=>setSketchPickerColor("#FFFFFF")} className={`colorbox whitebox ${"#FFFFFF"===sketchPickerColor?"checked":""}`}></div>
          <>
            {
              colors.map((ele,idx)=>(
                <div onClick={()=>setSketchPickerColor(ele)} key={idx} style={{backgroundColor:ele}} className={`colorbox ${ele===sketchPickerColor?"checked":""}`}></div>
              ))
            }
          </>
        </div>
    </ColorPickerDiv1>
  );
}

export default ColorPicker;
