class HTMLPreviewerComponent extends Component {
  constructor (props) {
    super(props)
    this.state = {
      visible: false,
      placement: 'right',
      sampleTemplateContent: [],
      selectedContent: this.props.content ? this.props.content : '',
      // selectedContentName: '',
      contentChangeing: false,
      showDrawer: false,
      addFieldIndex: 1,
      fieldTypeSelected: 'text-area',
      addMoreFieldButtonVisible: false,
      selectedUploadFileType: '',
      fileUrl: [{
        logo: '',
        header: '',
        footerlogo: '',
        whatsappLogo: '',
        phoneLogo: '',
        emailLogo: ''
      }],
      selectedTemplateIndex: this.props.selectedTemplateIndex || '',
      showBottomLogo: false,
      templateStateChange: !!(this.props.content || this.props.html),
      tagSelected: null,
      tagIndex: null,
      contentType: null,
      borderBottomColor: '',
      showHeaderModel: false,
      showColorSelectionModal: false,
      showFinalPrivewModal: false
    }
    this.handleChangeComments = this.handleChangeComments.bind(this)
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      UploadDataUrl,
      UploadDataUrlMessage,
      sampleTemplate
    } = nextProps
    if (UploadDataUrlMessage === 'success') {
      const { fileUrl, selectedUploadFileType } = this.state
      const obj = { ...fileUrl[0] }
      // https://eslint.org/docs/rules/no-prototype-builtins
      // for more details read from here
      const objHasOwnProperty = Object.prototype.hasOwnProperty.call(obj, selectedUploadFileType)
      if (objHasOwnProperty) {
        obj[selectedUploadFileType] = UploadDataUrl
        this.setState({
          fileUrl: [obj]
        })
      }
      this.handelLogoUpdate(UploadDataUrl, selectedUploadFileType)
      this.props.resetNotificationsRedux(['templateUploadURl', 'templateUploadURlMessage'])
    }
    this.setState({
      sampleTemplateContent: sampleTemplate
    })
  }

  // updateFunctionalComponent() {
  //   // Logic to update the functional component
  //   // You might need to manage the state or props passed to the functional component here
  //   // For simplicity, I'm just rendering the functional component with updated state
  //   const { tagSelected } = this.state;
  //   const temporaryDocument = this.state.selectedContent
  //   const parser = new DOMParser()
  //   const parsedHTML = parser.parseFromString(temporaryDocument, 'text/html')
  //   this.functionalComponent = <HeaderImage tagSelected={th} html={parsedHTML} dummyRequest={dummyRequest} onChange={this.handleChangeComments} onClick={this.handleOnOpenDrawer} />;
  //   // Render the updated functional component wherever needed
  //   // Example: this.setState({ functionalComponent });
  // }

  componentDidMount = async () => {
    await this.props.getsampleTemplate()
    await this.props.getTopLevelAttributes()
  }

  componentDidUpdate (prevProps) {
    if (this.props.html !== prevProps.html || this.props.content !== prevProps.content) {
      const newContent = this.props.html || this.props.content
      if (newContent && newContent !== this.state.selectedContent) {
        this.setState({
          selectedContent: newContent,
          templateStateChange: true
        })
      }
    }

    if (this.props.selectedTemplateIndex !== prevProps.selectedTemplateIndex &&
      this.props.selectedTemplateIndex !== undefined) {
      this.setState({
        selectedTemplateIndex: this.props.selectedTemplateIndex
      })
    }
  }

  handelLogoUpdate = (logo, type) => {
    const temporaryDocument = this.state.selectedContent
    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(temporaryDocument, 'text/html')
    let logoContainer, children
    switch (type) {
      case 'logo':
        logoContainer = parsedHTML.querySelector('.template-logo')
        children = logoContainer.children
        if (this.state.tagIndex === children.length) {
          const img = document.createElement('img')
          img.classList.add(`img${children.length}`)
          img.setAttribute('src', logo)
          img.setAttribute('width', '300')
          img.setAttribute('height', '200')
          logoContainer.appendChild(img)
          this.updateState(parsedHTML, this.state.tagIndex)
        } else {
          // children[this.st]
        }
        // this.props.resetNotificationsRedux(['UploadDataUrl', null])
        // this.props.resetNotificationsRedux(['UploadDataUrlMessage', null])
        // this.props.resetNotificationCore()
        this.updateState(parsedHTML)
        break
      case 'header':
        parsedHTML.querySelector('.template-banner').src = logo
        parsedHTML.querySelector('.template-banner').minWidth = 340
        parsedHTML.querySelector('.template-banner').style = 'margin-top: 0px; border-radius: 16px 16px 0 0'
        this.updateState(parsedHTML)
        this.props.resetNotificationsRedux(['templateUploadURl', 'templateUploadURlMessage'])

        break
      case 'footerlogo':
        parsedHTML.querySelector('.template-bottom-logo').src = logo
        this.updateState(parsedHTML)
        this.props.resetNotificationsRedux(['templateUploadURl', 'templateUploadURlMessage'])

        break
      case 'emailLogo':
        parsedHTML.querySelector('.template-email-logo').src = logo
        this.updateState(parsedHTML)
        break
      case 'whatsappLogo':
        parsedHTML.querySelector('.template-whatsapp-logo').src = logo
        this.updateState(parsedHTML)
        break
      case 'phoneLogo':
        parsedHTML.querySelector('.template-telephone-logo').src = logo
        this.updateState(parsedHTML)
        break
      default: return null
    }
  }

  async handleChangeComments (info) {
    if (info.file.status === 'done' || info.file.status === 'error') {
      // const isLt10KB = info.file.size / 1024 / 1024 < 0.01
      const isGt20MB = info.file.size / 1024 / 1024 > 20
      // if (isLt10KB) {
      //   message.error('File is to small, min 10kb')
      //   return
      // }
      if (isGt20MB) {
        message.error('File is to big, max 20mb')
        return
      }
      if (!isGt20MB) { // eslint-disable-line
        const file = info.file.originFileObj
        this.setState({
          filename: file.name,
          filesize: file.size,
          file,
          fileType: info.file.type
        })
        this.startUpload(file)
      } else {
        message.error('File is not supported')
      }
    }
  }

  startUpload = (file) => {
    // this.setState({ loading: true, noshowingModal: true })
    const formData = new FormData()
    formData.append('file', file)
    this.props.startUploadTemplate({ formData })
  }

  handleCloseDrawer = () => {
    this.setState({
      showDrawer: false,
      addMoreFieldButtonVisible: false,
      showColorSelectionModal: false
    })
  }

  handleOnToggleFinalPreview = () => {
    this.setState({
      showFinalPrivewModal: !this.state.showFinalPrivewModal
    })
  }

  serialLizeHTML = (data) => {
    return data.documentElement.innerHTML
  }

  updateState =(data, i, tag, type) => {
    this.setState({
      selectedContent: new XMLSerializer().serializeToString(data),
      templateStateChange: true,
      tagSelected: tag,
      tagIndex: i,
      contentType: type
    }, () => {
      if (!tag) {
        const a = document.getElementById('demo')
        const temporaryDocument = this.state.selectedContent
        const parser = new DOMParser()
        const parsedHTML = parser.parseFromString(temporaryDocument, 'text/html')
        renderTemplate(parsedHTML, a, this.updateState)
      }
    })
  }

  updateContent = (value) => {
    const temporaryDocument = this.state.selectedContent
    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(temporaryDocument, 'text/html')
    const templateContentChange = parsedHTML.querySelector('.template-content')
    templateContentChange.innerHTML = value
    this.setState({
      selectedContent: new XMLSerializer().serializeToString(parsedHTML),
      templateStateChange: true
    })
  }

  updateBgColor = (value) => {
    const temporaryDocument = this.state.selectedContent
    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(temporaryDocument, 'text/html')
    const table = parsedHTML.querySelector('body table')
    table.style.backgroundColor = value
    this.setState({
      selectedContent: new XMLSerializer().serializeToString(parsedHTML),
      templateStateChange: true
    })
  }

  handleCreateFooterElm = ({ label = '', elementType = '', parent = null, defaultValue = '' } = {}) => {
    const labelElm = document.createElement('label')
    const div = document.createElement('div')
    const data = document.createElement(elementType)

    div.setAttribute('class', 'key-field')
    data.setAttribute('class', 'key-field')
    labelElm.innerText = label
    Object.assign(data, { defaultValue })

    div.appendChild(labelElm)
    div.appendChild(data)
    parent.appendChild(div)

    return { data }
  }

  handleCreateFooterImageUpload = ({ label, parent, currentSrc, iconSelector } = {}) => {
    const outerDiv = document.createElement('div')
    outerDiv.setAttribute('class', 'key-field footer-icon-upload')

    const labelElm = document.createElement('label')
    labelElm.innerText = label

    // Preset Icons Dropdown container
    const { presetContainer, presetSelect, presetPreviewImg } = this.createPresetContainer()

    // Build the structure
    outerDiv.appendChild(labelElm)
    outerDiv.appendChild(presetContainer)
    parent.appendChild(outerDiv)

    return { presetSelect, presetPreviewImg }
  }

  createRadioContainer = (iconSelector) => {
    const container = document.createElement('div')
    container.setAttribute('class', 'radio-container')
    Object.assign(container.style, {
      marginBottom: '10px',
      display: 'flex',
      flexDirection: 'column',
      gap: '8px'
    })

    const createRadio = (value, labelText) => {
      const wrapper = document.createElement('label')
      wrapper.style.cursor = 'pointer'
      if (value === 'url') wrapper.style.marginRight = '15px'

      const radio = document.createElement('input')
      radio.setAttribute('type', 'radio')
      radio.setAttribute('name', `icon-type-${iconSelector}`)
      radio.setAttribute('value', value)
      radio.style.marginRight = '5px'
      if (value === 'url') radio.checked = true

      wrapper.appendChild(radio)
      wrapper.appendChild(document.createTextNode(labelText))
      container.appendChild(wrapper)

      return radio
    }

    const radioUrl = createRadio('url', 'URL')
    const radioPreset = createRadio('preset', 'Preset Icons')
    const radioUpload = createRadio('upload', 'Upload Image')

    return { container, radios: { radioUrl, radioPreset, radioUpload } }
  }

  createUrlInputContainer = (currentSrc) => {
    const urlContainer = document.createElement('div')
    urlContainer.setAttribute('class', 'url-input-container')
    Object.assign(urlContainer.style, {
      display: 'flex',
      alignItems: 'center',
      marginBottom: '10px'
    })

    const urlInput = document.createElement('input')
    urlInput.setAttribute('type', 'text')
    urlInput.setAttribute('class', 'icon-url-input')
    urlInput.setAttribute('placeholder', 'Enter image URL')
    urlInput.value = currentSrc || ''
    Object.assign(urlInput.style, {
      flex: '1',
      marginRight: '10px'
    })

    const urlApplyBtn = document.createElement('button')
    urlApplyBtn.setAttribute('type', 'button')
    urlApplyBtn.setAttribute('class', 'apply-url-btn')
    urlApplyBtn.innerText = 'Apply'

    urlContainer.appendChild(urlInput)
    urlContainer.appendChild(urlApplyBtn)

    return { urlContainer, urlInput, urlApplyBtn }
  }

  createPresetContainer = () => {
    const presetContainer = document.createElement('div')
    presetContainer.setAttribute('class', 'preset-dropdown-container')
    Object.assign(presetContainer.style, {
      display: 'block',
      marginBottom: '10px'
    })

    const presetSelect = document.createElement('select')
    presetSelect.setAttribute('class', 'icon-preset-select')
    Object.assign(presetSelect.style, {
      width: '100%',
      display: 'block',
      padding: '8px',
      borderRadius: '4px',
      border: '1px solid #ddd'
    })

    const presetIcons = [
      { label: 'Select an icon...', value: '' },
      { label: 'Phone Classic', value: 'https://cdn-icons-png.flaticon.com/512/724/724664.png' },
      { label: 'Phone Modern', value: 'https://cdn-icons-png.flaticon.com/512/455/455705.png' },
      { label: 'Phone Call', value: 'https://cdn-icons-png.flaticon.com/512/597/597177.png' },
      { label: 'Mobile Phone', value: 'https://cdn-icons-png.flaticon.com/512/15/15874.png' },
      { label: 'WhatsApp Square', value: 'https://cdn-icons-png.flaticon.com/512/4423/4423697.png' },
      { label: 'Email Envelope', value: 'https://cdn-icons-png.flaticon.com/512/561/561127.png' },
      { label: 'Email Modern', value: 'https://cdn-icons-png.flaticon.com/512/732/732200.png' },
      { label: 'Email Outline', value: 'https://cdn-icons-png.flaticon.com/512/542/542638.png' },
      { label: 'Email At Sign', value: 'https://cdn-icons-png.flaticon.com/512/893/893257.png' },
      { label: 'Website', value: 'https://cdn-icons-png.flaticon.com/512/1006/1006771.png' },
      { label: 'Facebook PNG', value: `${BASE_IMG_URL_S3}/tap_insurance_edm/white_icons/fb.png` },
      { label: 'Twitter PNG', value: `${BASE_IMG_URL_S3}/tap_insurance_edm/white_icons/TW.png` },
      { label: 'Email PNG', value: `${BASE_IMG_URL_S3}/tap_insurance_edm/white_icons/email_white_icon.png` },
      { label: 'Instagram PNG', value: `${BASE_IMG_URL_S3}/tap_insurance_edm/white_icons/ig_new.png` },
      { label: 'Linkedin PNG', value: `${BASE_IMG_URL_S3}/tap_insurance_edm/white_icons/linkedin_new.png` },
      { label: 'Whatsapp PNG', value: `${BASE_IMG_URL_S3}/tap_insurance_edm/white_icons/whatsapp_white_icon.png` }
    ]

    presetIcons.forEach(icon => {
      const option = document.createElement('option')
      option.value = icon.value
      option.textContent = icon.label
      presetSelect.appendChild(option)
    })

    const presetPreviewImg = document.createElement('img')
    presetPreviewImg.setAttribute('class', 'preset-icon-preview')
    Object.assign(presetPreviewImg.style, {
      width: '30px',
      height: '30px',
      marginTop: '10px',
      border: '1px solid #ddd',
      borderRadius: '4px',
      display: 'none'
    })

    presetContainer.appendChild(presetSelect)
    presetContainer.appendChild(presetPreviewImg)

    return { presetContainer, presetSelect, presetPreviewImg }
  }

  createUploadContainer = (currentSrc, iconSelector) => {
    const uploadContainer = document.createElement('div')
    uploadContainer.setAttribute('class', 'upload-container')
    Object.assign(uploadContainer.style, {
      display: 'none',
      alignItems: 'center'
    })

    const previewImg = document.createElement('img')
    previewImg.setAttribute('class', 'icon-preview')
    previewImg.src = currentSrc || ''
    Object.assign(previewImg.style, {
      width: '30px',
      height: '30px',
      marginRight: '10px',
      border: '1px solid #ddd',
      borderRadius: '4px'
    })

    const fileInput = document.createElement('input')
    fileInput.setAttribute('type', 'file')
    fileInput.setAttribute('accept', 'image/*')
    fileInput.setAttribute('class', 'icon-upload-input')
    fileInput.setAttribute('data-icon-selector', iconSelector)
    fileInput.style.display = 'none'

    const uploadBtn = document.createElement('button')
    uploadBtn.setAttribute('type', 'button')
    uploadBtn.setAttribute('class', 'upload-icon-btn')
    uploadBtn.innerText = 'Choose File'
    uploadBtn.onclick = () => fileInput.click()

    uploadContainer.appendChild(previewImg)
    uploadContainer.appendChild(uploadBtn)
    uploadContainer.appendChild(fileInput)

    return { uploadContainer, fileInput, previewImg, uploadBtn }
  }

  setupIconHandlers = (imgElm, iconInputs, parsedHTML) => {
    const { presetSelect, presetPreviewImg } = iconInputs

    // Handle preset selection
    presetSelect.addEventListener('change', () => {
      const selectedUrl = presetSelect.value
      if (selectedUrl) {
        presetPreviewImg.src = selectedUrl
        presetPreviewImg.style.display = 'block'
        imgElm.src = selectedUrl
        this.updateSerializedContent(parsedHTML)
      } else {
        presetPreviewImg.style.display = 'none'
      }
    })
  }

  updateSerializedContent = (parsedHTML) => {
    this.setState({
      selectedContent: new XMLSerializer().serializeToString(parsedHTML),
      templateStateChange: true
    })
  }

  handleFooterIconAndText = (parsedHTML, selector, iconLabel, textLabel, parent) => {
    const imgElm = parsedHTML.querySelector(selector)
    const textElm = this.findTextElement(imgElm, selector)

    if (imgElm) {
      const iconInputs = this.handleCreateFooterImageUpload({
        label: iconLabel,
        parent: parent,
        currentSrc: imgElm.src,
        iconSelector: selector.replace(/[^\w]/g, '-')
      })

      this.setupIconHandlers(imgElm, iconInputs, parsedHTML)
    }

    if (textElm) {
      const { data } = this.handleCreateFooterElm({
        elementType: 'textarea',
        label: textLabel,
        parent: parent,
        defaultValue: textElm?.href ?? textElm?.textContent ?? ''
      })

      data.addEventListener('input', (e) => {
        if (textElm?.href) {
          textElm.href = e.target.value
        } else {
          textElm.textContent = e.target.value
        }
        this.updateSerializedContent(parsedHTML)
      })
    }
  }

  findTextElement = (imgElm, selector) => {
    if (!imgElm) return null

    // Different selectors have different DOM structures
    if (selector === 'img[alt="call-ic"]') {
      return imgElm?.parentElement?.nextElementSibling?.querySelector('b') ||
            imgElm?.nextElementSibling?.querySelector('b')
    } else if (selector === 'img[alt="email-ic"]') {
      return imgElm?.parentElement?.nextElementSibling?.querySelector('a b')
    } else if (selector === 'img[alt="customer-support-ic"]') {
      return imgElm?.nextElementSibling?.querySelector('a b')
    } else if (selector === 'img[alt="linkedin-ic"]') {
      return imgElm?.parentElement
    } else if (selector === 'img[alt="x-ic"]') {
      return imgElm?.parentElement
    } else if (selector === 'img[alt="instagram-ic"]') {
      return imgElm?.parentElement
    } else if (selector === 'img[alt="facebook-ic"]') {
      return imgElm?.parentElement
    } else {
      return imgElm?.nextElementSibling?.querySelector('b')
    }
  }

  handleOnOpenDrawer = (val, idx) => {
    this.setState({ showDrawer: true })

    const drawerContent = document.getElementById('demo')
    drawerContent.innerHTML = ''

    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(this.state.selectedContent, 'text/html')

    switch (val) {
      case 'logoClick':
        this.setState({ showHeaderModel: true })
        break

      case 'logo':
        this.setState({
          addMoreFieldButtonVisible: false,
          selectedUploadFileType: 'logo',
          tagIndex: idx
        })
        break

      case 'header':
        this.setState({
          addMoreFieldButtonVisible: false,
          showDrawer: false,
          selectedUploadFileType: 'header'
        })
        break

      case 'heading':
        this.handleHeadingEdit(drawerContent, parsedHTML)
        break

      case 'changeContent':
        this.setState({ addMoreFieldButtonVisible: true })
        break

      case 'themeSelection':
        this.setState({ showColorSelectionModal: true })
        break

      case 'footer-logo':
        this.setState({
          addMoreFieldButtonVisible: false,
          showDrawer: false,
          selectedUploadFileType: 'footerlogo'
        })
        break

      case 'footer-details':
        this.handleFooterDetails(drawerContent, parsedHTML)
        break

      default:
        break
    }
  }

  handleHeadingEdit = (parent, parsedHTML) => {
    this.setState({ addMoreFieldButtonVisible: false })

    const outerDiv = document.createElement('div')
    outerDiv.setAttribute('class', 'key-field')

    const textarea = document.createElement('textarea')
    textarea.setAttribute('class', 'key-field')
    textarea.setAttribute('type', 'text')

    const headerElm = parsedHTML.querySelector('.template-header')
    textarea.value = headerElm.textContent
    textarea.innerHTML = headerElm.textContent

    textarea.addEventListener('input', (e) => {
      headerElm.textContent = e.target.value
      this.updateSerializedContent(parsedHTML)
    })

    outerDiv.appendChild(textarea)
    parent.appendChild(outerDiv)
  }

  handleFooterDetails = (parent, parsedHTML) => {
    this.setState({
      addMoreFieldButtonVisible: false,
      showBottomLogo: !this.state.showBottomLogo
    })

    const footerItems = [
      { selector: 'img[alt="call-ic"]', iconLabel: 'Phone Icon', textLabel: 'Phone' },
      { selector: 'img[alt="whatsapp-ic"]', iconLabel: 'WhatsApp Icon', textLabel: 'Whatsapp No.' },
      { selector: 'img[alt="zalo-ic"]', iconLabel: 'Zalo Icon', textLabel: 'Zalo' },
      { selector: 'img[alt="email-ic"]', iconLabel: 'Email Icon', textLabel: 'Email' },
      { selector: 'img[alt="customer-support-ic"]', iconLabel: 'Website Icon', textLabel: 'Website URL' },

      { selector: 'img[alt="facebook-ic"]', iconLabel: 'Facebook Icon', textLabel: 'Facebook URL' },
      { selector: 'img[alt="instagram-ic"]', iconLabel: 'Instagram Icon', textLabel: 'Instagram URL' },
      { selector: 'img[alt="x-ic"]', iconLabel: 'X Icon', textLabel: 'X URL' },
      { selector: 'img[alt="linkedin-ic"]', iconLabel: 'LinkedIn Icon', textLabel: 'LinkedIn URL' }
    ]

    footerItems.forEach(item => {
      this.handleFooterIconAndText(parsedHTML, item.selector, item.iconLabel, item.textLabel, parent)
    })
  }

  reRenderContentFields =(data) => {
    const a = document.getElementById('demo')
    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(data, 'text/html')
    renderTemplate(parsedHTML, a, this.updateState)
  }

  addMoreField = (divName, type) => {
    const { addFieldIndex, selectedContent } = this.state
    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(selectedContent, 'text/html')
    const self = this
    switch (type) {
      case 'text-area': {
        const mainHTML = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('template-content-change')[0]
        if (mainHTML) {
          const childNodemainHTML = mainHTML.children[0]
          const newdiv = document.createElement('div')
          const LineBreakTag = document.createElement('br')
          const tableRow = document.createElement('TR')
          const tableData = document.createElement('TD')
          const ptag = document.createElement('P')
          const inputTag = document.createElement('textarea')
          inputTag.setAttribute('type', 'text')
          inputTag.setAttribute('class', 'key-field')
          inputTag.setAttribute('name', addFieldIndex)
          ptag.setAttribute('id', addFieldIndex)
          newdiv.setAttribute('class', 'key-field')
          ptag.setAttribute('class', 'template-content')
          const buttonDelete = document.createElement('INPUT')
          buttonDelete.setAttribute('type', 'button')
          buttonDelete.setAttribute('class', 'delete-button')
          buttonDelete.setAttribute('id', addFieldIndex)
          newdiv.appendChild(inputTag)
          newdiv.appendChild(buttonDelete)
          newdiv.appendChild(LineBreakTag)
          newdiv.addEventListener('input', function (e) {
            const mainHTML = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('previewer-template')[0].querySelector('table')
            const bodyData = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('template-content-change')[0].children[0]
            const selectedTag = bodyData.getElementsByClassName('template-content').namedItem(e.target.name)
            selectedTag.innerText = e.target.value
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').children[0].remove()
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').appendChild(mainHTML.children[0])
            self.setState({
              selectedContent: new XMLSerializer().serializeToString(parsedHTML),
              templateStateChange: true
            }, () => {
              self.reRenderContentFields(self.state.selectedContent)
            })
          })
          buttonDelete.addEventListener('click', function (e) {
            const mainHTML = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('previewer-template')[0].querySelector('table')
            const bodyData = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('template-content-change')[0].children[0]
            const selectedTag = bodyData.getElementsByClassName('template-content').namedItem(e.target.id)
            selectedTag.parentNode.parentNode.remove()
            newdiv.remove()
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').children[0].remove()
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').appendChild(mainHTML.children[0])
            self.setState({
              selectedContent: new XMLSerializer().serializeToString(parsedHTML),
              templateStateChange: true
            }, () => {
              self.reRenderContentFields(self.state.selectedContent)
            })
          }, { capture: true })

          tableData.appendChild(ptag)
          tableRow.appendChild(tableData)
          childNodemainHTML.appendChild(tableRow)
          document.getElementById(divName).appendChild(newdiv)
          this.setState({
            addFieldIndex: this.state.addFieldIndex + 1
          })
        } else {
          alert('Selected Field Type Not Present In Template')
        }
      }
        break
      case 'table-row' : {
        const mainHTML = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('template-content-change-table')[0]
        if (mainHTML) {
          const childNodemainHTML = mainHTML.children[0]
          const newdiv = document.createElement('div')
          const LineBreakTag = document.createElement('br')
          const inputTagKey = document.createElement('input')
          const inputTagValue = document.createElement('input')
          const buttonDelete = document.createElement('INPUT')
          newdiv.setAttribute('class', 'key-field')
          inputTagKey.setAttribute('class', 'input-filed')
          inputTagValue.setAttribute('class', 'input-filed')
          inputTagKey.setAttribute('type', 'text')
          inputTagValue.setAttribute('type', 'text')
          inputTagKey.setAttribute('name', addFieldIndex)
          inputTagValue.setAttribute('name', addFieldIndex)
          buttonDelete.setAttribute('type', 'button')
          buttonDelete.setAttribute('class', 'delete-button')
          buttonDelete.setAttribute('id', addFieldIndex)
          const tableRow = document.createElement('TR')
          const tableDataKey = document.createElement('TD')
          const tableDataValue = document.createElement('TD')
          tableDataKey.setAttribute('class', 'template-content-key')
          tableDataKey.setAttribute('id', addFieldIndex)
          tableDataValue.setAttribute('class', 'template-content-value')
          tableDataValue.setAttribute('id', addFieldIndex)

          newdiv.appendChild(inputTagKey)
          newdiv.appendChild(inputTagValue)
          newdiv.appendChild(buttonDelete)
          newdiv.appendChild(LineBreakTag)

          inputTagKey.addEventListener('input', function (e) {
            const mainHTML = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('previewer-template')[0].querySelector('table')
            const bodyData = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('template-content-change')[0].children[0]
            const selectedTag = bodyData.getElementsByClassName('template-content-key').namedItem(e.target.name)
            selectedTag.innerText = e.target.value
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').children[0].remove()
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').appendChild(mainHTML.children[0])
            self.setState({
              selectedContent: new XMLSerializer().serializeToString(parsedHTML),
              templateStateChange: true
            }, () => {
              self.reRenderContentFields(self.state.selectedContent)
            })
          })
          inputTagValue.addEventListener('input', function (e) {
            const mainHTML = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('previewer-template')[0].querySelector('table')
            const bodyData = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('template-content-change')[0].children[0]
            const selectedTag = bodyData.getElementsByClassName('template-content-value').namedItem(e.target.name)
            selectedTag.innerText = e.target.value
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').children[0].remove()
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').appendChild(mainHTML.children[0])
            self.setState({
              selectedContent: new XMLSerializer().serializeToString(parsedHTML),
              templateStateChange: true
            }, () => {
              self.reRenderContentFields(self.state.selectedContent)
            })
          })
          buttonDelete.addEventListener('click', function (e) {
            const mainHTML = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('previewer-template')[0].querySelector('table')
            const bodyData = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('template-content-change')[0].children[0]
            const selectedTagKey = bodyData.getElementsByClassName('template-content-key').namedItem(e.target.id)
            selectedTagKey.parentNode.remove()
            newdiv.remove()
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').children[0].remove()
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').appendChild(mainHTML.children[0])
            self.setState({
              selectedContent: new XMLSerializer().serializeToString(parsedHTML),
              templateStateChange: true
            }, () => {
              self.reRenderContentFields(self.state.selectedContent)
            })
          }, { capture: true })

          tableRow.appendChild(tableDataKey)
          tableRow.appendChild(tableDataValue)
          childNodemainHTML.appendChild(tableRow)
          document.getElementById(divName).appendChild(newdiv)
          this.setState({
            addFieldIndex: this.state.addFieldIndex + 1
          })
        } else {
          alert('Selected Field Type Not Present In Template')
        }
      }
        break
      case 'list-type' : {
        const mainHTML = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('template-content-change-list')[0]
        if (mainHTML) {
          const newdiv = document.createElement('div')
          const LineBreakTag = document.createElement('br')
          const ListTag = document.createElement('li')
          const inputTag = document.createElement('input')
          newdiv.setAttribute('class', 'key-field')
          inputTag.setAttribute('class', 'key-field')
          inputTag.setAttribute('type', 'text')
          inputTag.setAttribute('name', addFieldIndex)
          ListTag.setAttribute('id', addFieldIndex)
          ListTag.setAttribute('class', 'template-content-list')
          const buttonDelete = document.createElement('INPUT')
          buttonDelete.setAttribute('type', 'button')
          buttonDelete.setAttribute('class', 'delete-button')
          buttonDelete.setAttribute('id', addFieldIndex)
          newdiv.appendChild(inputTag)
          newdiv.appendChild(buttonDelete)
          newdiv.appendChild(LineBreakTag)

          inputTag.addEventListener('input', function (e) {
            const mainHTML = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('previewer-template')[0].querySelector('table')
            const bodyData = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('template-content-change')[0].children[0]
            const selectedTag = bodyData.getElementsByClassName('template-content-list').namedItem(e.target.name)
            selectedTag.innerText = e.target.value
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').children[0].remove()
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').appendChild(mainHTML.children[0])
            self.setState({
              selectedContent: new XMLSerializer().serializeToString(parsedHTML),
              templateStateChange: true
            }, () => {
              self.reRenderContentFields(self.state.selectedContent)
            })
          })
          buttonDelete.addEventListener('click', function (e) {
            const mainHTML = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('previewer-template')[0].querySelector('table')
            const bodyData = document.getElementsByClassName('preview-template-style')[0].getElementsByClassName('template-content-change')[0].children[0]
            const selectedTag = bodyData.getElementsByClassName('template-content-list').namedItem(e.target.id)
            selectedTag.remove()
            newdiv.remove()
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').children[0].remove()
            parsedHTML.getElementsByTagName('body')[0].querySelector('table').appendChild(mainHTML.children[0])
            self.setState({
              selectedContent: new XMLSerializer().serializeToString(parsedHTML),
              templateStateChange: true
            }, () => {
              self.reRenderContentFields(self.state.selectedContent)
            })
          }, { capture: true })

          mainHTML.appendChild(ListTag)
          document.getElementById(divName).appendChild(newdiv)
          this.setState({
            addFieldIndex: this.state.addFieldIndex + 1
          })
        } else {
          alert('Selected Field Type Not Present In Template')
        }
      }
        break
      default: return null
    }
  }

  selectTemplate = (index) => {
    const templateHtml = this.state.sampleTemplateContent[index].template_html

    const htmlWithMeta = addCustomMetaTags(templateHtml, {
      'template-id': this.state.sampleTemplateContent[index].template_id || index,
      'template-name': this.state.sampleTemplateContent[index].template_name || '',
      'selected-at': new Date().toISOString()
    })

    this.setState({
      selectedTemplateIndex: index,
      selectedContent: htmlWithMeta,
      showDrawer: false,
      templateStateChange: false
    }, () => {
      this.updateContent(' ')
    })
  }

  handleSelectField = (e) => {
    this.setState({
      fieldTypeSelected: e
    })
  }
  // variableChange =(index, value)=>{

  //   // return value.split(' ').splice(index, 0, this.state.selectedValue).join(',')
  // }
  handleSelectVariable =(val) => {
    const a = document.getElementById('demo')
    const temporaryDocument = this.state.selectedContent
    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(temporaryDocument, 'text/html')
    renderTemplate(parsedHTML, a, this.updateState, val, this.state.tagSelected, this.state.tagIndex, this.state.contentType)
  }

  // htmlFunction =(data) => ('<!DOCTYPE html><html>' + data + '</html>')
  handleSubmittingHtml =() => {
    this.props.htmlContentFunction(this.state.selectedContent)
    this.setState({
      // selectedContent: '',
      // selectedTemplateIndex: -1,
      templateStateChange: true,
      showFinalPrivewModal: false
    })
  }

  selectFiledDataPopulate =(type) => {
    const { getPartnerProductTemplate, selectedProduct } = this.props
    const { borderBottomColor } = this.state
    const selectedProducts = _.get(getPartnerProductTemplate, 'products', []).length > 0 ? _.get(getPartnerProductTemplate, 'products', []).filter(item => Object.keys(item)[0] === selectedProduct) : []
    const selectPartner = _.get(getPartnerProductTemplate, 'partner', [])
    if (selectedProducts.length > 0) {
      const selectedProductValues = selectedProducts && Object.values(selectedProducts[0])[0]
      const footerColor = selectedProductValues.filter(item => (Object.keys(item)[0] === 'footerColor') && item.is_active)
      if ((footerColor.length > 0) && (borderBottomColor === '')) {
        this.setState({
          borderBottomColor: footerColor[0].footerColor
        })
      }
      const objectItem = selectedProductValues.filter(item => (Object.keys(item)[0] === type) && item.is_active)
      return objectItem
    } else if (selectPartner.length > 0) {
      const objectItem = selectPartner.filter(item => (Object.keys(item)[0] === type) && item.is_active)
      const footerColor = selectPartner.filter(item => (Object.keys(item)[0] === 'footerColor') && item.is_active)
      if ((footerColor.length > 0) && (borderBottomColor === '')) {
        this.setState({
          borderBottomColor: footerColor[0].footerColor
        })
      }
      return objectItem
    } else {
      return []
    }
  }

  selectImage =(value, type) => {
    // this.setState({

    // })
    this.handelLogoUpdate(value, type)
  }

  render () {
    const { addMoreFieldButtonVisible, showBottomLogo, templateStateChange, sampleTemplateContent = [], selectedTemplateIndex, showColorSelectionModal, filename, showFinalPrivewModal } = this.state
    const { uploadingImageLoading } = this.props
    const parser = new DOMParser()
    const parsedHTML = parser.parseFromString(this.state.selectedContent, 'text/html')
    const customDrawerClasses = (this.state.showDrawer ? 'show' : '')
    return (
      <PreviewerComponent>
        <Spin spinning={sampleTemplateContent?.length === 0} tip='Sample Template Loading .....'>
          <div className='sample-container box-shadow-on marginB20'>
            {
              sampleTemplateContent?.map((item, index) => (
                <div key={`selected-template-${index}`} className='sample-template-box'>
                  <label class='custom-checkbox'>
                    <input checked={selectedTemplateIndex === index} type='checkbox' />
                    <span class='checkmark' />
                  </label>
                  <div className={` ${item.template_name} sample-template-box-inner`} dangerouslySetInnerHTML={{ __html: item.template_html }} />
                  <div className='text-center padding10'>
                    <p className='template-text'>{item.template_name}</p>
                    {
                      selectedTemplateIndex === index
                        ? <div className='selectedBtn selectBtn' onClick={() => this.setState({ selectedTemplateIndex: -1 })}>SELECTED</div>
                        : templateStateChange
                          ? (
                            <Popconfirm
                              title='All UnsavedChanges Lost Without Saving Template'
                              okText='YES'
                              cancelText='NO'
                              onConfirm={() => this.selectTemplate(index)}
                            >
                              <Button className='selectBtn'>SELECT</Button>
                            </Popconfirm>
                            )
                          : (
                            <div className='selectBtn' onClick={() => this.selectTemplate(index)}>SELECT</div>
                            )

                    }
                  </div>
                </div>
              ))
            }
          </div>
        </Spin>
        {
          this.state.selectedContent !== '' &&
            <Spin spinning={uploadingImageLoading === true} tip='Updating Your Template'>
              <div className='sample-previewer-section box-shadow-on'>
                  <div className='preview-template-style'>
                  <div className='ql-editor template-preview-content' style={{ width: '100%', padding: 0 }} dangerouslySetInnerHTML={{ __html: this.state.selectedContent }} />
                </div>
                <div className='sample-template-controls'>
                  <div className={`customise-drawer ${customDrawerClasses}`}>
                    <div className='custom-drawer-content'>
                      <div className='drawer-header'>
                        <span className='close-button' onClick={this.handleCloseDrawer}>
                          <Icon class='close-button' type='close-circle' />
                        </span>
                        {this.state.showHeaderModel && <HeaderImage html={parsedHTML} dummyRequest={dummyRequest} onChange={this.handleChangeComments} onClick={this.handleOnOpenDrawer} />}

                      </div>
                      <div className='drawer-body'>
                        <div id='demo' />
                        {
                          addMoreFieldButtonVisible &&
                            <>
                              <TextEditor previousContent={this.state.selectedContent} updateContent={this.updateContent} />

                            </>
                        }
                        {showColorSelectionModal && <ColorPicker updateBgColor={this.updateBgColor} />}
                      </div>
                    </div>
                  </div>
                  <div className='marginTB16px'>
                    {parsedHTML.querySelector('.logo') && (
                      <div className='padding15 text-center'>
                        <Radio.Group onChange={(e) => this.selectImage(e.target.value, 'logo')}>
                          {
                            [...this.selectFiledDataPopulate('logo')].map((item, index) => {
                              return (
                                <Radio value={Object.values(item)[0]} key={`selected-filed${index}`}>
                                  <label className='fieldLabel'>Change Logo</label>
                                  <ImagePreviewer imageUrl={Object.values(item)[0]} />
                                </Radio>
                              )
                            })
                          }
                        </Radio.Group>
                      </div>
                    )}
                    {
                    parsedHTML.querySelector('.template-banner') &&
                      <div className='padding15'>
                        <div className='newText'>Header Image</div>
                        <Upload
                          name='file'
                          showUploadList={false}
                          multiple={false}
                          customRequest={dummyRequest}
                          onChange={file => this.handleChangeComments(file)}
                        >
                          <div
                            className='upload-dummy-box'
                            onClick={() => this.handleOnOpenDrawer('header')}
                          >
                            <p className='newText2'>{filename}</p>
                            <img className='icon' src={UPLOAD_ICON} alt='UPLOAD ICON' />
                          </div>
                        </Upload>
                      </div>
                  }
                    <div className='padding15'>
                      <div className='newText'>Body Text</div>
                      <TextEditor previousContent={this.state.selectedContent} updateContent={this.updateContent} />
                    </div>
                    <ColorPicker updateBgColor={this.updateBgColor} />
                    {
                      parsedHTML.querySelector('.template-bottom-logo') &&
                        <div className='padding15 text-center'>
                          <Radio.Group onChange={(e) => this.selectImage(e.target.value, 'footerlogo')}>
                            {
                              [...this.selectFiledDataPopulate('footerlogo')].map((item, index) => {
                                return (
                                  <Radio value={Object.values(item)[0]} key={`footer-logo${index}`}>
                                    <label className='fieldLabel'>Change Footer Logo</label>
                                    <ImagePreviewer imageUrl={Object.values(item)[0]} />
                                  </Radio>
                                )
                              })
                            }
                          </Radio.Group>
                        </div>
                    }
                    <div className='padding15 text-center'>
                      <Button
                        className='ant-btn-radius'
                        onClick={() => this.handleOnOpenDrawer('footer-details')}
                      >Change Footer Details
                      </Button>
                    </div>

                    {
                      showBottomLogo &&
                        <div>
                          <div className='padding15 text-center'>
                            <Radio.Group onChange={(e) => this.selectImage(e.target.value, 'whatsappLogo')}>
                              {
                                [...this.selectFiledDataPopulate('whatsappLogo')].map((item, index) => {
                                  return (
                                    <Radio value={Object.values(item)[0]} key={`whatsappLogo${index}`}>
                                      <label className='fieldLabel'>Change WhatsappLogo</label>
                                      <ImagePreviewer imageUrl={Object.values(item)[0]} />
                                      {/* <img src={Object.values(item)[0]} style={{width:50, height:50}}/> */}
                                    </Radio>
                                  )
                                })
                              }
                            </Radio.Group>
                          </div>
                          <div className='padding15 text-center'>
                            <Radio.Group onChange={(e) => this.selectImage(e.target.value, 'phoneLogo')}>
                              {
                                [...this.selectFiledDataPopulate('phoneLogo')].map((item, index) => {
                                  return (
                                    <Radio value={Object.values(item)[0]} key={`phoneLogo${index}`}>
                                      <label className='fieldLabel'>Change Phone Logo</label>
                                      <ImagePreviewer imageUrl={Object.values(item)[0]} />
                                      {/* <img src={Object.values(item)[0]} style={{width:50, height:50}}/> */}
                                    </Radio>
                                  )
                                })
                              }
                            </Radio.Group>
                          </div>
                          <div className='padding15 text-center'>
                            <Radio.Group onChange={(e) => this.selectImage(e.target.value, 'emailLogo')}>
                              {
                                [...this.selectFiledDataPopulate('emailLogo')].map((item, index) => {
                                  return (
                                    <Radio value={Object.values(item)[0]} key={`emailLogo${index}`}>
                                      <label className='fieldLabel'>Change Email Logo</label>
                                      <ImagePreviewer imageUrl={Object.values(item)[0]} />
                                      {/* <img src={Object.values(item)[0]} style={{width:50, height:50}}/> */}
                                    </Radio>
                                  )
                                })
                              }
                            </Radio.Group>
                          </div>
                        </div>
                    }
                  </div>
                  <div className='padding15 text-center marginT-auto'>
                    <Button className='ant-btn-radius fillColor' type='primary' block onClick={this.handleOnToggleFinalPreview}>Save Changes</Button>
                  </div>
                </div>
              </div>
            </Spin>
        }
        {showFinalPrivewModal && (
          <FinalPriviwer>
            <div className='modal' style={{ width: "800px" }}>
              <div className='preview ql-editor' dangerouslySetInnerHTML={{ __html: this.state.selectedContent }} />
              <div className='buttons'>
                <div onClick={this.handleOnToggleFinalPreview} className='button secondary'>EDIT</div>
                <div onClick={this.handleSubmittingHtml} className='button primary'>SAVE</div>
              </div>
            </div>
          </FinalPriviwer>
        )}
      </PreviewerComponent>
    )
  }
}
HTMLPreviewerComponent.propTypes = {
  sampleTemplate: PropTypes.array.isRequired
}

export default connect(state => ({
  sampleTemplate: state.Notifications.getTemplateData,
  UploadDataUrl: state.Notifications.templateUploadURl,
  uploadingImageLoading: state.Loading.UPLOAD_NOTIFICATIONS_TEMPLATE_ATTRIBUTE,
  UploadDataUrlMessage: state.Notifications.templateUploadURlMessage,
  sampleAttributesData: state.Notifications.topLevelAttributes,
  getPartnerProductTemplate: state.Partner.getPartnerProductTemplateData
}), {
  getsampleTemplate,
  updatesampleTemplate,
  startUploadTemplate,
  getTopLevelAttributes,
  resetNotificationsRedux,
  resetNotificationCore
})(HTMLPreviewerComponent)
