export const isTemplateBuilderContent = (htmlContent) => {
  const parser = new DOMParser()
  const parsedHTML = parser.parseFromString(htmlContent, 'text/html')
  const metaTag = parsedHTML.querySelector('meta[name="x-template-builder"]')
  return metaTag?.getAttribute('content') === 'true'
}

export const getTemplateMetaData = (htmlContent) => {
  const parser = new DOMParser()
  const parsedHTML = parser.parseFromString(htmlContent, 'text/html')
  const metaTags = parsedHTML.querySelectorAll('meta[name^="x-"]')

  const metaData = {}
  metaTags.forEach((tag) => {
    const name = tag.getAttribute('name').replace('x-', '')
    const content = tag.getAttribute('content')
    metaData[name] = content
  })

  return metaData
}

export const addCustomMetaTags = (htmlContent, metaData = {}) => {
  const parser = new DOMParser()
  const parsedHTML = parser.parseFromString(htmlContent, 'text/html')

  const defaultMeta = {
    'template-builder': 'true',
    'created-at': new Date().toISOString(),
    'builder-version': '1.0',
    ...metaData
  }

  let head = parsedHTML.querySelector('head')
  if (!head) {
    head = document.createElement('head')
    if (parsedHTML.documentElement) {
      parsedHTML.documentElement.insertBefore(head, parsedHTML.body)
    }
  }

  Object.entries(defaultMeta).forEach(([name, content]) => {
    let metaTag = parsedHTML.querySelector(`meta[name="x-${name}"]`)

    if (metaTag) {
      metaTag.setAttribute('content', content)
    } else {
      metaTag = document.createElement('meta')
      metaTag.setAttribute('name', `x-${name}`)
      metaTag.setAttribute('content', content)
      head.appendChild(metaTag)
    }
  })

  return new XMLSerializer().serializeToString(parsedHTML)
}

export const addFontsToEmailHtml = (htmlString) => {
  const FONT_MARKER = '/* EMAIL_FONTS_ADDED */'

  if (htmlString.includes(FONT_MARKER)) {
    return htmlString
  }

  const fontStyles = `
    ${FONT_MARKER}
    /* Email-safe font families */
    .font-sans, .sans-serif {
      font-family: Arial, Helvetica, 'Helvetica Neue', sans-serif;
    }
    .font-serif, .serif {
      font-family: Georgia, 'Times New Roman', Times, serif;
    }
    .font-mono, .monospace {
      font-family: 'Courier New', Courier, monospace;
    }
    body {
      font-family: Arial, Helvetica, 'Helvetica Neue', sans-serif;
    }
    h1, h2, h3, h4, h5, h6, p, span {
      line-height: 1;
      margin-top: 0;
      padding-top: 0;
      margin-bottom: 0;
      padding-bottom: 0;
      font-weight: normal;
      mso-line-height-rule: exactly;
    }
    .ql-align-right {
      text-align: right !important;
    }
    .ql-align-center {
      text-align: center !important;
    }
    .ql-align-left {
      text-align: left !important;
    }

    .template-content {
      text-wrap: wrap !important;
      word-break: break-word !important;
    }
  `

  let result = htmlString

  if (result.match(/<style[^>]*>/)) {
    result = result.replace(/(<style[^>]*>)/, `$1${fontStyles}`)
  } else if (result.includes('</head>')) {
    result = result.replace('</head>', `<style>${fontStyles}</style></head>`)
  } else {
    result = `<style>${fontStyles}</style>${result}`
  }

  return result
}
